"""Brute-force solvers written from the problem definitions (for testing)."""

from __future__ import annotations

from itertools import combinations, product


def solve_vertex_cover(instance: dict) -> bool:
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k < 0:
        return False
    if k >= n:
        return True
    for size in range(0, k + 1):
        for subset in combinations(range(n), size):
            chosen = set(subset)
            if all(u in chosen or v in chosen for u, v in edges):
                return True
    return False


def solve_sat(instance: dict) -> bool:
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for values in product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            if not any(
                (values[abs(lit) - 1] if lit > 0 else not values[abs(lit) - 1])
                for lit in clause
            ):
                ok = False
                break
        if ok:
            return True
    return False
